html:
{% set t = ticket_for_print(doc.name) %}
{% set L = t.by_key %}
<style>
  .sst { font-family: 'Poppins', Arial, sans-serif; font-size: 11px; color: #000; background: #fff; max-width: 780px; margin: 0 auto; position: relative; }
  .sst h1 { font-size: 16px; margin: 0; font-weight: 700; letter-spacing: .02em; }
  .sst .meta { font-size: 11px; margin-top: 2px; }
  .sst table { width: 100%; border-collapse: collapse; margin-bottom: 10px; }
  .sst th, .sst td { border: 1px solid #000; padding: 4px 6px; text-align: left; vertical-align: top; }
  .sst th { font-weight: 600; background: #fff; }
  .sst .lab { width: 22%; font-weight: 600; }
  .sst .box { min-height: 16px; white-space: pre-line; }
  .sst h2 { font-size: 12px; margin: 10px 0 4px; text-transform: uppercase; letter-spacing: .04em; }
  .sst .banner { border: 2px solid #000; text-align: center; font-weight: 700; font-size: 18px; padding: 6px; margin-bottom: 10px; letter-spacing: .06em; }
  .sst .foot { margin-top: 14px; font-size: 10px; text-align: right; }
</style>
<div class="sst">
  {% if not t.printable %}
  <div class="banner">{% if t.percent < 100 %}INCOMPLETE — {{ t.percent }}%{% else %}STOPPED PLAN — NOT FOR ISSUE{% endif %}</div>
  {% endif %}
  <h1>Spray Application Ticket (MOLFM27)</h1>
  <div class="meta"><strong>Work Order:</strong> {{ doc.name }} &nbsp;&nbsp; <strong>Week:</strong> {{ L.app_week.value or "" }}</div>
  <br>
  <table>
    <tr><td class="lab">Block</td><td class="box">{{ L.block.value or "" }}</td><td class="lab">Farm</td><td class="box">{{ L.farm.value or "" }}</td></tr>
    <tr><td class="lab">Location</td><td class="box">{{ L.location.value or "" }}</td><td class="lab">Area (ha)</td><td class="box">{{ L.area_ha.value or "" }}</td></tr>
    <tr><td class="lab">Crop</td><td class="box">{{ L.crop.value or "" }}</td><td class="lab">Variety</td><td class="box">{{ L.variety.value or "" }}</td></tr>
    <tr><td class="lab">Crop stage</td><td class="box">{{ L.crop_stage.value or "" }}</td><td class="lab">Operator</td><td class="box">{{ L.operator.value or "" }}</td></tr>
  </table>

  <h2>Products</h2>
  <table>
    <thead><tr><th>Product</th><th>Composition</th><th>Quantity</th><th>Rate</th></tr></thead>
    <tbody>
    {% for p in t.products %}
      <tr>
        <td class="box">{{ p.item_name }}</td>
        <td class="box">{{ p.ingredients | join(", ") }}</td>
        <td class="box">{{ p.qty }} {{ p.uom }}</td>
        <td class="box">{{ p.rate or "" }}</td>
      </tr>
    {% else %}
      <tr><td class="box">&nbsp;</td><td class="box"></td><td class="box"></td><td class="box"></td></tr>
    {% endfor %}
    </tbody>
  </table>

  <table>
    <tr><td class="lab">Equipment</td><td class="box">{{ L.equipment.value or "" }}</td><td class="lab">Method of application</td><td class="box">{{ L.method.value or "" }}</td></tr>
    <tr><td class="lab">Water and dilution</td><td class="box" colspan="3">{{ L.water.value or "" }}</td></tr>
  </table>

  <h2>Sign-off</h2>
  <table>
    <thead><tr><th>Role</th><th>Name</th><th>Date / time</th></tr></thead>
    <tbody>
    {% for key in ["prepared", "authorized", "issued", "collected", "applied"] %}
      {% set line = L[key] %}
      <tr>
        <td class="lab">{{ line.label }}</td>
        <td class="box">{% if line.filled %}{{ line.value.split(" · ")[0] if " · " in line.value else "" }}{% endif %}</td>
        <td class="box">{% if line.filled %}{{ line.value.split(" · ")[1] if " · " in line.value else line.value }}{% endif %}</td>
      </tr>
    {% endfor %}
    </tbody>
  </table>

  <div class="foot">Field/FSQM/2</div>
</div>
